mapper.select:
SELECT v.id, v.wave_no, v.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, v.status, COALESCE(stat.task_count, 0) AS task_count, COALESCE(stat.done_count, 0) AS done_count, COALESCE(stat.total_qty, 0) AS total_qty, v.finish_time, v.remark, v.create_time FROM wms_wave v LEFT JOIN base_warehouse w ON w.id = v.warehouse_id LEFT JOIN (SELECT wave_id, COUNT(*) AS task_count, SUM(status = 30) AS done_count, SUM(qty) AS total_qty FROM wms_task WHERE deleted = 0 AND wave_id IS NOT NULL GROUP BY wave_id) stat ON stat.wave_id = v.id WHERE v.deleted = 0
AND v.status = #{q.status}
AND v.warehouse_id = #{q.warehouseId}
AND (v.wave_no LIKE CONCAT('%', #{q.keyword}, '%') OR v.remark LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY v.id DESC
